// GENERATED from the packaged seed for `idle-reaper.ts` — do not edit, and do not commit.
// The record is the source of truth; this file is a derived cache so tsc/vite/vitest can resolve
// `@/app/console/lib/idleReaper` after the original module was retired. Regenerate with `npm run emit:records`.
// Idle session reaping (#849) — decide which background console PTYs to reap to bound
// memory when many projects accumulate hidden `claude` processes. PURE decision: given a
// snapshot of live panes + the reaper config + the clock, return the pane ids to reap. The
// hook (useIdleReaper) does the side effects (pty_kill + mark dormant); the store renders a
// dormant placeholder and resumes on focus. Framework-free + unit-tested.
//
// Reaping is non-destructive: a worktree/cwd persists on disk and the pane resumes via the
// existing relaunch path, so a reaped session is recoverable, not lost.

import type { SessionRole } from "@/shared/lib/session/sessionRoles";

/** A live pane the reaper evaluates. */
export interface ReaperPane {
  paneId: string;
  /** Live PTY status: "run" = mid-turn (never reaped), "idle"/"on" = at rest. */
  status: "run" | "on" | "idle";
  role: SessionRole;
  /** Epoch ms of this pane's last activity (last status change / output). */
  lastActivityMs: number;
  /** The pane the user is currently watching — never reaped. */
  focused: boolean;
  /** Already dormant (reaped) — skip; nothing to reap twice. */
  dormant: boolean;
  /** DECLARED maintenance (#4025): this worker emitted `bsc-maintain` — everything it owns is done
   *  and it is standing by for the director to dispatch into. Distinct from ordinary idling, which is
   *  why it gets its own rule below rather than a shorter `workerIdleMs`. */
  maintaining?: boolean;
}

// NOTE: the DECISION is not here any more. `isReapable` / `panesToReap` / `thresholdFor` / `tickFor`
// moved to `src-tauri/src/console/pty/reap.rs`, in the process that owns the PTY sessions — a policy in
// the renderer stopped bounding anything the moment the renderer died, which it did five times in one
// day, leaving 17 sessions alive with nothing able to reap them. What remains here is the CONFIG the
// user edits in Settings, which the frontend REPORTS to the backend (`pty_set_reap_policy`).
export interface ReaperConfig {
  /** Which policy generation wrote this config — see [`REAPER_CONFIG_VERSION`]. Absent on anything
   *  persisted before every role became reapable, which is exactly what makes the migration safe. */
  version?: number;
  /** Master switch. */
  enabled: boolean;
  /** Idle threshold (ms) for reapable project/planner sessions. */
  idleMs: number;
  /** Idle threshold (ms) for workers + the director — conservative. `null` ⇒ never reap
   *  them (the default), since they idle legitimately (parked on a dep / the director). */
  workerIdleMs: number | null;
  /** Idle threshold (ms) for the app-owned STUDIO sessions (designer/librarian/architect, #3357).
   *  A studio session deliberately outlives the page that opened it — it stays warm on TerminalHost
   *  so its Glance node can morph into it — so this is how long it may sit with NO surface showing
   *  it before being reclaimed. Separate from `idleMs` because the trigger is different: the studio
   *  reaper counts *unwatched* time (viewer count 0), not time since last output.
   *  OPTIONAL for back-compat: a config persisted before #3357 has no such key, and zustand's
   *  persist replaces the whole object rather than merging, so readers MUST fall back to
   *  {@link DEFAULT_STUDIO_IDLE_MS} rather than trusting it to be present. */
  studioIdleMs?: number;
  /** How long a session INSIDE a running agent may print nothing before being reaped. Separate from
   *  `idleMs` because the two protect different things: `idleMs` is for a session whose agent has
   *  exited and has nothing in flight, this one can interrupt a turn. See
   *  {@link DEFAULT_SILENCE_CEILING_MS}. */
  silenceCeilingMs?: number;
}

/** The grace before an idle pane is reaped — SECONDS, not minutes.
 *
 *  Safe at this length because of what gates it: a pane is only evaluated once its agent has exited
 *  (see `thresholdFor`), so this is time spent as a bare shell prompt, not thinking time. It is also
 *  the floor for `useIdleReaper`'s poll tick — a grace shorter than the tick is rounded up to it. */
export const DEFAULT_IDLE_MS = 10 * 1000;

/** Default idle grace before an unwatched studio session is reclaimed (#3357). Also the fallback
 *  for a `ReaperConfig` persisted before the key existed. */
export const DEFAULT_STUDIO_IDLE_MS = DEFAULT_IDLE_MS;


/** The effective studio idle threshold for a config, tolerating a pre-#3357 persisted object AND one
 *  written before every role became reapable.
 *
 *  The version gate has to be here too, not only in {@link effectiveIdleMs}. The measured persisted
 *  config carries an EXPLICIT `studioIdleMs: 1800000`, so the `??` fallback never fires for it and a
 *  studio session would have kept the retired half-hour while every other role dropped to seconds. */
export function studioIdleMs(cfg: ReaperConfig): number {
  if (cfg.version !== REAPER_CONFIG_VERSION) return DEFAULT_STUDIO_IDLE_MS;
  const stored = cfg.studioIdleMs;
  return Number.isFinite(stored) && (stored as number) >= 0 ? (stored as number) : DEFAULT_STUDIO_IDLE_MS;
}
/** The grace this config actually applies, reconciling a config persisted before every role became
 *  reapable.
 *
 *  VERSIONED, NOT SNIFFED. The first attempt migrated any config whose `idleMs` still equalled the
 *  retired 30-minute default — which also silently overrode anyone who had DELIBERATELY chosen thirty
 *  minutes, and broke three existing tests that meant exactly that. A stored value cannot say whether
 *  it was chosen; a version can.
 *
 *  So: a config from before this change carries no `version` and takes the new grace once. Anything
 *  written since carries the current one and is honoured, whatever it says.
 *
 *  THE MIGRATION MATTERS MORE THAN THE DEFAULT: zustand persists the whole object, so lowering
 *  `DEFAULT_REAPER_CONFIG` alone changes nothing on a machine that already has one — measured here as
 *  `{enabled: true, idleMs: 1800000, workerIdleMs: null, studioIdleMs: 1800000}`.
 */
export const REAPER_CONFIG_VERSION = 3;

/** The default SILENCE CEILING: how long a session still inside an agent may print nothing before the
 *  backend reaps it.
 *
 *  Minutes, not seconds, and for a reason the short grace does not share: this is the only threshold
 *  that can interrupt real work. A `run` pane is one whose agent has NOT exited, so the ceiling has to
 *  outlast the slowest plausible turn — a local model's first response after a cold load is minutes.
 *  What it catches is the launched-and-parked session: measured 2026-08-31, fifteen agents alive for
 *  909s having printed nothing at all. */
export const DEFAULT_SILENCE_CEILING_MS = 5 * 60 * 1000;

/** The effective silence ceiling for a config, version-gated exactly as {@link effectiveIdleMs} is. */
export function silenceCeilingMs(cfg: ReaperConfig): number {
  if (cfg.version !== REAPER_CONFIG_VERSION) return DEFAULT_SILENCE_CEILING_MS;
  const stored = cfg.silenceCeilingMs;
  return Number.isFinite(stored) && (stored as number) > 0
    ? (stored as number)
    : DEFAULT_SILENCE_CEILING_MS;
}

export function effectiveIdleMs(cfg: ReaperConfig): number {
  if (cfg.version !== REAPER_CONFIG_VERSION) return DEFAULT_IDLE_MS;
  const stored = cfg.idleMs;
  return Number.isFinite(stored) && stored >= 0 ? stored : DEFAULT_IDLE_MS;
}
/** The packaged defaults: on, one seconds-long grace for EVERY role. Surfaced in Settings; persisted
 *  — which is why the version above exists, since a machine that already has one never reads these. */
export const DEFAULT_REAPER_CONFIG: ReaperConfig = {
  version: REAPER_CONFIG_VERSION,
  enabled: true,
  idleMs: DEFAULT_IDLE_MS,
  // Retained so a persisted object round-trips, and no longer consulted: every role takes the same
  // grace. Left non-null so an older reader cannot interpret it as "never".
  workerIdleMs: DEFAULT_IDLE_MS,
  studioIdleMs: DEFAULT_STUDIO_IDLE_MS,
  silenceCeilingMs: DEFAULT_SILENCE_CEILING_MS,
};

