// The reaper CONFIG — what the user edits and the frontend reports.
//
// The DECISION is deliberately not tested here any more, because it is not here: `isReapable`,
// `panesToReap`, `thresholdFor` and `tickFor` moved to `src-tauri/src/console/pty/reap.rs` and are
// tested there. A frontend copy would be a second policy that can disagree with the one that actually
// runs — and the reason for the move is that the frontend copy stopped running whenever the renderer
// died, which it did five times in one day while 17 sessions stayed alive.
import { describe, it, expect } from "vitest";
import {
  effectiveIdleMs,
  silenceCeilingMs,
  DEFAULT_IDLE_MS,
  DEFAULT_SILENCE_CEILING_MS,
  DEFAULT_STUDIO_IDLE_MS,
  studioIdleMs,
  REAPER_CONFIG_VERSION,
  DEFAULT_REAPER_CONFIG,
  type ReaperConfig,
} from "@/app/console/lib/idleReaper";

describe("the reaper config", () => {
  it("ships defaults that are internally consistent", () => {
    expect(DEFAULT_REAPER_CONFIG.version).toBe(REAPER_CONFIG_VERSION);
    expect(effectiveIdleMs(DEFAULT_REAPER_CONFIG)).toBe(DEFAULT_IDLE_MS);
    expect(silenceCeilingMs(DEFAULT_REAPER_CONFIG)).toBe(DEFAULT_SILENCE_CEILING_MS);
    // The ceiling protects a RUNNING agent and must be far longer than the grace for an exited one,
    // or a slow local turn would be reaped as though it were parked.
    expect(silenceCeilingMs(DEFAULT_REAPER_CONFIG)).toBeGreaterThan(
      effectiveIdleMs(DEFAULT_REAPER_CONFIG) * 10,
    );
  });

  it("migrates a config persisted before every role became reapable", () => {
    // Lowering the default alone changes nothing on a machine that already has one: zustand persists
    // the WHOLE object, measured as `{enabled:true, idleMs:1800000, workerIdleMs:null, …}`.
    const persisted = { enabled: true, idleMs: 30 * 60_000, workerIdleMs: null } as ReaperConfig;
    expect(effectiveIdleMs(persisted)).toBe(DEFAULT_IDLE_MS);

    // VERSIONED RATHER THAN SNIFFED. Migrating any config whose value equalled the retired default
    // would also override someone who had DELIBERATELY chosen it. A stored number cannot say whether
    // it was chosen; a version can.
    const chosen: ReaperConfig = { ...persisted, version: REAPER_CONFIG_VERSION };
    expect(effectiveIdleMs(chosen)).toBe(30 * 60_000);
    expect(effectiveIdleMs({ ...chosen, idleMs: 5 * 60_000 })).toBe(5 * 60_000);

    // Nonsense falls back rather than reaping instantly or never.
    expect(effectiveIdleMs({ ...chosen, idleMs: Number.NaN })).toBe(DEFAULT_IDLE_MS);
    expect(effectiveIdleMs({ ...chosen, idleMs: -1 })).toBe(DEFAULT_IDLE_MS);
  });

  it("version-gates the SILENCE CEILING too, which is new in this version", () => {
    // A config written before the ceiling existed carries no value for it AND an older version, so it
    // must take the packaged one rather than read as "0" — which would reap every running agent on the
    // next sweep.
    const old = { enabled: true, idleMs: 10_000, workerIdleMs: null } as ReaperConfig;
    expect(silenceCeilingMs(old)).toBe(DEFAULT_SILENCE_CEILING_MS);

    const chosen: ReaperConfig = { ...old, version: REAPER_CONFIG_VERSION, silenceCeilingMs: 90_000 };
    expect(silenceCeilingMs(chosen)).toBe(90_000);
    // Zero is not "reap immediately" here — it is an unset field, and taking it literally would kill
    // every running agent. Same for a negative or non-finite value.
    expect(silenceCeilingMs({ ...chosen, silenceCeilingMs: 0 })).toBe(DEFAULT_SILENCE_CEILING_MS);
    expect(silenceCeilingMs({ ...chosen, silenceCeilingMs: -1 })).toBe(DEFAULT_SILENCE_CEILING_MS);
    expect(silenceCeilingMs({ ...chosen, silenceCeilingMs: Number.NaN })).toBe(
      DEFAULT_SILENCE_CEILING_MS,
    );
  });

  it("migrates the STUDIO threshold too, which the `??` fallback could never reach", () => {
    // The measured persisted config carries an EXPLICIT `studioIdleMs: 1800000`, so the nullish
    // fallback never fires for it and studio sessions would have kept the retired half-hour.
    const persisted = {
      enabled: true,
      idleMs: 30 * 60_000,
      workerIdleMs: null,
      studioIdleMs: 30 * 60_000,
    } as ReaperConfig;
    expect(studioIdleMs(persisted)).toBe(DEFAULT_STUDIO_IDLE_MS);
    expect(studioIdleMs({ ...persisted, version: REAPER_CONFIG_VERSION })).toBe(30 * 60_000);
  });

  it("bumps the version when a policy change must override what is already persisted", () => {
    // v3 adds the silence ceiling. A machine sitting on v2 has no value for it, so it must be treated
    // as pre-migration for BOTH thresholds — which only works if the version actually moved.
    expect(REAPER_CONFIG_VERSION).toBeGreaterThan(2);
  });
});
